import java.util.*;
import java.io.*;

public class Main {
    static int n, t, counter;
    static int[][] source_cap = new int[10][10];
    static int[][] sink_cap = new int[10][10];
    static int[][] source_num = new int[10][10];
    static int[][] sink_num = new int[10][10];
    static int[][][] plant = new int[10][10][61];
    static int[][] flo = new int[200][200];
    static int[] dr = {0, 0, -1, 1};
    static int[] dc = {-1, 1, 0, 0};

    static boolean is_valid(int r, int c) {
        return r >= 0 && r < n && c >= 0 && c < n;
    }

    static int get_path() {
        int[] parent = new int[counter + 1];
        Arrays.fill(parent, -1);
        parent[0] = 0;
        Stack<Integer> dfs = new Stack<>();
        dfs.push(0);
        while (!dfs.isEmpty()) {
            int top = dfs.pop();
            if (top == counter)
                break;
            for (int i = 0; i <= counter; i++) {
                if (flo[top][i] != 0 && parent[i] == -1) {
                    parent[i] = top;
                    dfs.push(i);
                }
            }
        }
        if (parent[counter] == -1)
            return 0;
        int ans = Integer.MAX_VALUE;
        int pos = counter;
        while (pos != 0) {
            ans = Math.min(ans, flo[parent[pos]][pos]);
            pos = parent[pos];
        }
        pos = counter;
        while (pos != 0) {
            flo[parent[pos]][pos] -= ans;
            flo[pos][parent[pos]] += ans;
            pos = parent[pos];
        }
        return ans;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());

        String[] inp = new String[n];
        for (int i = 0; i < n; i++) {
            inp[i] = br.readLine();
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                char ch = inp[i].charAt(j);
                if (ch == 'Y' || ch == 'Z') {
                    plant[i][j][0] = ch - 'X';
                    source_cap[i][j] = 0;
                } else {
                    plant[i][j][0] = 0;
                    source_cap[i][j] = ch - '0';
                }
            }
        }
        for (int i = 0; i < n; i++) {
            inp[i] = br.readLine();
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                char ch = inp[i].charAt(j);
                if (ch == 'Y' || ch == 'Z') {
                    plant[i][j][0] = ch - 'X';
                    sink_cap[i][j] = 0;
                } else {
                    plant[i][j][0] = 0;
                    sink_cap[i][j] = ch - '0';
                }
            }
        }
        for (int curr_time = 1; curr_time <= t; curr_time++) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    plant[i][j][curr_time] = plant[i][j][curr_time - 1];
                }
            }
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (plant[i][j][curr_time - 1] == 2) {
                        for (int k = 0; k < 4; k++) {
                            int ni = i + dr[k];
                            int nj = j + dc[k];
                            if (is_valid(ni, nj)) {
                                if (plant[ni][nj][curr_time - 1] == 0)
                                    plant[ni][nj][curr_time] = 2;
                            }
                        }
                    }
                }
            }
        }
        counter = 1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (source_cap[i][j] != 0) {
                    source_num[i][j] = counter++;
                } else {
                    source_num[i][j] = -1;
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (sink_cap[i][j] != 0) {
                    sink_num[i][j] = counter++;
                } else {
                    sink_num[i][j] = -1;
                }
            }
        }
        Queue<int[]> bfs = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (source_cap[i][j] == 0)
                    continue;
                bfs.offer(new int[]{0, i, j});
                boolean[][] vis = new boolean[n][n];
                vis[i][j] = true;
                while (!bfs.isEmpty()) {
                    int[] top = bfs.poll();
                    int curr_time = top[0], r = top[1], c = top[2];
                    if (sink_cap[r][c] != 0)
                        flo[source_num[i][j]][sink_num[r][c]] = 10000;
                    if (curr_time == t)
                        continue;
                    if (plant[r][c][curr_time] != 0)
                        continue;
                    for (int k = 0; k < 4; k++) {
                        int nr = r + dr[k];
                        int nc = c + dc[k];
                        if (is_valid(nr, nc) && plant[nr][nc][curr_time] == 0 && !vis[nr][nc]) {
                            bfs.offer(new int[]{curr_time + 1, nr, nc});
                            vis[nr][nc] = true;
                        }
                    }
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (source_cap[i][j] != 0)
                    flo[0][source_num[i][j]] = source_cap[i][j];
                if (sink_cap[i][j] != 0)
                    flo[sink_num[i][j]][counter] = sink_cap[i][j];
            }
        }
        int ans = 0;
        while (true) {
            int temp = get_path();
            if (temp == 0)
                break;
            ans += temp;
        }
        System.out.println(ans);
    }
}
